using System.Security.Cryptography;
using Yubico.YubiKit.Core.Abstractions;
using Yubico.YubiKit.Core.Cryptography;
using Yubico.YubiKit.Core.Devices;
using Yubico.YubiKit.Core.Protocols.SmartCard.Scp;
using Yubico.YubiKit.Core.Sessions;
using Yubico.YubiKit.SecurityDomain;

IYubiKey device = await YubiKeyManager.FindFirstAsync();
await using var session = await device.CreateSecurityDomainSessionAsync();

foreach (var keyInfo in await session.ListKeyInformationAsync())
{
    Console.WriteLine(keyInfo.KeyReference);
}

using var scpKeyParameters = Scp03KeyParameters.Default;
await using var session = await device.CreateSecurityDomainSessionAsync(
    new SessionCreationOptions { ScpKeyParameters = scpKeyParameters });

IReadOnlyList<KeyInfo> keys = await session.ListKeyInformationAsync();

byte[] keyMaterial = RandomNumberGenerator.GetBytes(48);
try
{
    // Escrow keyMaterial before you send it: the device will not give it back.
    using var newKeys = new StaticKeys(keyMaterial.AsSpan(0, 16), keyMaterial.AsSpan(16, 16), keyMaterial.AsSpan(32, 16));
    await session.PutKeyAsync(new KeyReference(ScpKid.SCP03, Kvn: 0x02), newKeys, replaceKvn: 0);
}
finally
{
    CryptographicOperations.ZeroMemory(keyMaterial);
}

const byte ClaGlobalPlatform = 0x80;

// Common instructions
const byte InsGetData = 0xCA;
const byte InsPutKey = 0xD8;
const byte InsInitializeUpdate = 0x50;
const byte InsExternalAuthenticate = 0x82;
const byte InsInternalAuthenticate = 0x88;
const byte InsDelete = 0xE4;
const byte InsGenerateKey = 0xF1;
const byte InsPerformSecurityOperation = 0x2A;

// TLV tags for data encoding
const int TagKeyInformationTemplate = 0xE0;
const byte TagControlReference = 0xA6;
const byte TagKidKvn = 0x83;

var keyInfo = await session.ListKeyInformationAsync(cancellationToken);
foreach (var entry in keyInfo)
{
    logger.LogDebug(
        "Key: KID={Kid:X2}, KVN={Kvn:X2}",
        entry.KeyReference.Kid,
        entry.KeyReference.Kvn);
}

[SkippableTheory]
[WithYubiKey(ConnectionType = ConnectionType.SmartCard, MinFirmware = "5.4.3")]
public async Task MyTest(YubiKeyTestState state)
{
    using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(100));
    CancellationToken ct = timeout.Token;
    using var parameters = Scp03KeyParameters.Default;
    await state.WithSecurityDomainSessionAsync(
        resetBeforeUse: true,
        async session =>
        {
            var keyInfo = await session.ListKeyInformationAsync(ct);
            Assert.NotEmpty(keyInfo);
        },
        scpKeyParams: parameters,
        cancellationToken: ct);
}

[SkippableTheory]
[WithYubiKey(ConnectionType = ConnectionType.SmartCard, MinFirmware = "5.4.3")]
public async Task ListAfterReset_ContainsFactoryVersion(YubiKeyTestState state)
{
    using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(100));
    CancellationToken ct = timeout.Token;
    using var parameters = Scp03KeyParameters.Default;
    await state.WithSecurityDomainSessionAsync(
        resetBeforeUse: true,
        async session =>
        {
            var keys = await session.ListKeyInformationAsync(ct);
            Assert.Contains(keys, entry => entry.KeyReference.Kvn == 0xFF);
        },
        scpKeyParams: parameters,
        cancellationToken: ct);
}

[SkippableTheory]
[WithYubiKey(ConnectionType = ConnectionType.SmartCard, MinFirmware = "5.7.2")]
public async Task GeneratedKey_IsListedInNextSession(YubiKeyTestState state)
{
    using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(100));
    CancellationToken ct = timeout.Token;
    using var parameters = Scp03KeyParameters.Default;
    var keyRef = new KeyReference(ScpKid.SCP11b, 0x03);
    try
    {
        await state.WithSecurityDomainSessionAsync(
            resetBeforeUse: true,
            async session => { await session.GenerateKeyAsync(keyRef, cancellationToken: ct); },
            scpKeyParams: parameters,
            cancellationToken: ct);

        await state.WithSecurityDomainSessionAsync(
            resetBeforeUse: false,
            async session =>
            {
                var keys = await session.ListKeyInformationAsync(ct);
                Assert.Contains(keys, entry => entry.KeyReference.Kid == keyRef.Kid &&
                    entry.KeyReference.Kvn == keyRef.Kvn);
            },
            cancellationToken: ct);
    }
    finally
    {
        using var cleanup = new CancellationTokenSource(TimeSpan.FromSeconds(60));
        await state.ResetSecurityDomainAsync(cleanup.Token);
    }
}

